<script setup>
import { Head, Link } from '@inertiajs/vue3';
import PortalLayout from '@/Layouts/PortalLayout.vue';
import CustomerNavigation from '@/Components/Customer/CustomerNavigation.vue';
defineProps({ services: Array });
const money=(value,currency)=>new Intl.NumberFormat('en-NG',{style:'currency',currency}).format(Number(value));
const date=value=>value?new Intl.DateTimeFormat('en-NG',{dateStyle:'medium'}).format(new Date(`${value}T00:00:00`)):'No fixed expiry';
</script>
<template><Head title="My services"/><PortalLayout area="Customer Portal"><template #navigation><CustomerNavigation active="services"/></template><div class="mb-6 flex flex-wrap items-end justify-between gap-4"><div><p class="text-sm font-bold uppercase tracking-wider text-cyan-700">Customer account</p><h1 class="mt-2 text-3xl font-bold">My services</h1><p class="mt-2 text-slate-600">Manage your KernelBridge products, plans, renewal dates and subscription status.</p></div><Link :href="route('portal.services.create')" class="form-button">Add service</Link></div><p v-if="$page.props.flash.success" class="success-message mb-5">{{ $page.props.flash.success }}</p><div class="grid gap-5 lg:grid-cols-2"><article v-for="service in services" :key="service.uuid" class="rounded-2xl bg-white p-6 shadow-sm ring-1 ring-slate-200"><div class="flex items-start justify-between gap-4"><div><p class="text-sm text-slate-500">{{ service.number }}</p><h2 class="mt-1 text-xl font-bold text-[#0B3D6E]">{{ service.product }}</h2><p class="text-sm text-slate-600">{{ service.plan }} · {{ service.customer }}</p></div><span class="rounded-full bg-cyan-100 px-3 py-1 text-xs font-bold uppercase text-cyan-800">{{ service.status }}</span></div><dl class="mt-5 grid grid-cols-2 gap-4 text-sm"><div><dt class="text-slate-500">Price</dt><dd class="font-semibold">{{ money(service.price,service.currency) }} / {{ service.billing_cycle }}</dd></div><div><dt class="text-slate-500">Renewal / expiry</dt><dd class="font-semibold">{{ date(service.ends_at) }}</dd></div><div><dt class="text-slate-500">Started</dt><dd class="font-semibold">{{ date(service.starts_at) }}</dd></div><div><dt class="text-slate-500">Auto-renew</dt><dd class="font-semibold">{{ service.auto_renew ? 'Enabled' : 'Disabled' }}</dd></div></dl><div class="mt-5 flex items-center gap-4"><Link :href="route('portal.services.edit',service.uuid)" class="font-bold text-cyan-700">Manage service</Link><Link v-if="service.product_slug" :href="route('products.show',service.product_slug)" class="text-sm font-semibold text-slate-600">View product</Link></div></article><div v-if="!services.length" class="rounded-2xl bg-white p-10 text-center text-slate-500 ring-1 ring-slate-200">No services are attached to your account yet. Add a service to get started.</div></div></PortalLayout></template>
